#include <mysql_driver.h>
#include <mysql_connection.h>
#include <cppconn/statement.h>
#include <cppconn/resultset.h>
#include <string>
#include <memory>
#include <algorithm>
#include <cctype>

void searchProducts(sql::Connection* con, const std::string& searchTerm) {
    const bool valid = std::all_of(searchTerm.begin(), searchTerm.end(),
        [](unsigned char c) { return std::isalnum(c) || c == ' '; });
    if (!valid) return;
    std::string query = "SELECT * FROM products WHERE name LIKE '%" + searchTerm + "%'";
    std::unique_ptr<sql::Statement> stmt(con->createStatement());
    stmt->executeQuery(query);
}

