#include <sqlite3.h>
#include <vector>
sqlite3_stmt* buildTopScoresQuery(sqlite3* db, int N) {
    sqlite3_stmt* stmt = nullptr; sqlite3_prepare_v2(db, "SELECT score FROM scores ORDER BY score DESC LIMIT ?", -1, &stmt, nullptr); sqlite3_bind_int(stmt, 1, N); return stmt;
}
struct GameDatabase {
std::vector<int> getTopScores(sqlite3* db, int N) {
    sqlite3_stmt* stmt = buildTopScoresQuery(db, N);
    std::vector<int> scores;
    while (sqlite3_step(stmt) == SQLITE_ROW) scores.push_back(sqlite3_column_int(stmt, 0));
    sqlite3_finalize(stmt); return scores;
}};

#include <mysql_driver.h>
#include <mysql_connection.h>
#include <cppconn/statement.h>
#include <cppconn/resultset.h>
#include <cppconn/exception.h>
#include <algorithm>
#include <exception>
#include <functional>
#include <iostream>
#include <memory>
#include <set>
#include <string>

void handleLookupMessage(
    sql::Connection* connection,
    const std::string& networkMessage,
    std::function<void(int)> callback
) {
    if (connection == nullptr) {
        std::cerr << "Database connection is unavailable" << std::endl;
        callback(-1);
        return;
    }

    if (networkMessage.empty() || networkMessage.size() > 128) {
        std::cerr << "Invalid lookup message" << std::endl;
        callback(-1);
        return;
    }

    const std::set<std::string> allowedTables = {
        "users", "orders", "products"
    };
    const bool isKnownTable = std::any_of(
        allowedTables.begin(), allowedTables.end(),
        [&](const std::string& allowed) {
            return networkMessage.compare(0, allowed.size(), allowed) == 0;
        }
    );

    if (!isKnownTable) {
        std::cerr << "Lookup table is not recognized" << std::endl;
        callback(-1);
        return;
    }

    try {
        std::string query = "SELECT COUNT(*) FROM " + networkMessage;
        std::unique_ptr<sql::Statement> statement(
            connection->createStatement()
        );
        std::unique_ptr<sql::ResultSet> result(
            statement->executeQuery(query)
        );

        if (!result->next()) {
            std::cerr << "Lookup returned no result" << std::endl;
            callback(0);
            return;
        }

        const int rowCount = result->getInt(1);
        std::cout << "Lookup completed with " << rowCount << " rows" << std::endl;
        callback(rowCount);
    } catch (const sql::SQLException& error) {
        std::cerr << "Database lookup failed: " << error.what() << std::endl;
        callback(-1);
    } catch (const std::exception& error) {
        std::cerr << "Lookup processing failed: " << error.what() << std::endl;
        callback(-1);
    }
}

