#include <cppconn/connection.h>
#include <cppconn/prepared_statement.h>
#include <cppconn/resultset.h>
#include <cppconn/exception.h>
#include <iostream>
#include <memory>
#include <stdexcept>

void fetchPage(sql::Connection* con, int limit, int offset) {
    if (con == nullptr) {
        throw std::invalid_argument("Database connection is required");
    }
    if (limit <= 0 || offset < 0) {
        throw std::invalid_argument("Invalid pagination values");
    }

    try {
        std::unique_ptr<sql::PreparedStatement> pstmt(
            con->prepareStatement(
                "SELECT * FROM products LIMIT ? OFFSET ?"
            )
        );
        pstmt->setInt(1, limit);
        pstmt->setInt(2, offset);

        std::unique_ptr<sql::ResultSet> res(pstmt->executeQuery());

        while (res->next()) {
            std::cout << res->getString(1) << std::endl;
        }
    } catch (const sql::SQLException& e) {
        std::cerr << "Database error: " << e.what() << std::endl;
        throw;
    }
}

#include <vector>
#include <algorithm>

class Employee {
public:
    int id;
    double salary;
    Employee(int i, double s) : id(i), salary(s) {}
};

class EmployeeSorter {
public:
    std::vector<Employee> employees;
    void addEmployee(int id, double salary) {
        employees.emplace_back(id, salary);
    }
    void sortBySalary() {
        std::sort(employees.begin(), employees.end(), [](const Employee& a, const Employee& b) {
            return a.salary < b.salary;
        });
    }
};
